// TH18 v1.00a st07.ecl: MainSub03 -> GirlD01 / GirlD01_at (Extra rank 4).
// Source frames: first GirlD01 at MainSub03 frame 0, two more at +300.
// Card shell: 120-frame opening buffer, then the same three spawns 300 apart.

const TIME_LIMIT: int = 1680;
const OPENING_BUFFER: int = 120;

const TH18_BIG_BALL2: int = 656; // source etSprite(0, 19, 1)
const BULLET_COLOR: int = 1;
// Source etDist 16 minus ANIM(type 2, a=1) entry shift 4*0.6 = 2.4 px.
const BULLET_BIRTH_DIST: fx = 13.6fx;

xformdef DELAYED_ACCEL {
    // Source etEx WAIT(120) then VELTIME(a=60, r=4.0, s=current angle).
    wait(120);
    step_speed(4fx, 60);
}

// GirlD01_at: wait 60, 8 fired rings 70 frames apart.
async sub girl_shot() {
    wait(60);
    sh_reset(0);
    sh_sprite(0, TH18_BIG_BALL2, BULLET_COLOR);
    sh_aim(0, 1);       // source etAim(0, 2): player-aimed ring
    sh_ring(0, 1);
    sh_count(0, 32, 1);
    sh_speed(0, 0.6fx, 0fx); // source etSpeed(0, 0.6, 1.6), M=1 uses 0.6
    // Source etAngle(0, 0, 0.6981317): with one layer the second angle
    // contributes no bullet offset; keep its value on the layer step.
    sh_angle(0, 0deg, 40deg);
    sh_dist(0, BULLET_BIRTH_DIST);
    sh_xform(0, DELAYED_ACCEL);
    for i in 0..8 {
        sh_fire(0);
        wait(70);
    }
}

// GirlD01: one spawn's motion, boxes, and shot task.
async sub girl_main() {
    set_invuln(65535);
    set_hurtbox(16fx); // source setHurtbox(32, 32), circular first value / 2
    set_hitbox(12fx);  // source setHitbox(24, 24), circular first value / 2
    // Source moveVel(pi/2, 3) then moveVelTime(60, mode1, pi/2, 0).
    // mode1 is t^2; EASE_QUAD_IN interpolates 3 -> 0 over 60 frames.
    move_vel(0, 90deg, 3fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);
    spawn girl_shot();
    wait(400);
    // Source moveSpeedTime(120, mode1, 2): 0 -> 2 with t^2.
    move_speed(120, 2fx, EASE_QUAD_IN);
    wait(60);
    // Source jumps back to its 1000-frame wait loop and never deletes.
    loop { wait(1000); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -48fx, 1600, 0, 1000, 0, girl_main);
    wait(300);
    _ = spawn_enemy(160fx, -48fx, 1600, 0, 1000, 0, girl_main);
    _ = spawn_enemy(-160fx, -48fx, 1600, 0, 1000, 0, girl_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
